#[cfg(test)]
mod tests {
    use super::*;
    use ferrite_app::serde_json::json;
    #[test]
    fn tasks_distinguish_creation_from_detailed_terminal_result() {
        let mut task = json!({"taskId":"id", "createdAt":"now", "lastUpdatedAt":"now", "ttlMs":null,"status":"completed"});
        assert!(validate(&task, false).is_ok());
        assert!(validate(&task, true).is_err());
        task["result"] = json!({"content":[],"isError":true});
        assert!(validate(&task, true).is_ok());
        assert!(terminal(&task));
        assert!(!supported(&json!({"tasks":{}})));
        assert!(supported(&json!({"extensions":{EXTENSION:{}}})));
    }
    #[test]
    fn tasks_input_uses_results_not_rpc_envelopes() {
        assert!(validate_inputs(&json!({"ask":{"action":"accept","content":{"ok":true}}})).is_ok());
        assert!(validate_inputs(&json!({"ask":{"jsonrpc":"2.0","result":{}}})).is_err());
    }
}
